import{_ as o,c as s,o as a,ag as n}from"./chunks/framework.Bzez9NG9.js";const h=JSON.parse('{"title":"Models and logic","description":"Use SPACE AI to understand TM1 model structure and dependencies, review rules, feeders, and TurboIntegrator processes, and create or modify supported Planning Analytics objects.","frontmatter":{"title":"Models and logic","description":"Use SPACE AI to understand TM1 model structure and dependencies, review rules, feeders, and TurboIntegrator processes, and create or modify supported Planning Analytics objects.","keywords":["TM1","model structure","dependencies","cube rules","feeders","TurboIntegrator","TI","process code","create rules","update rules","create processes","update processes","views","subsets","code review"],"outline":"deep"},"headers":[],"relativePath":"doc/ai/models-and-logic.md","filePath":"doc/ai/models-and-logic.md"}'),t={name:"doc/ai/models-and-logic.md"};function r(i,e,d,l,c,p){return a(),s("div",null,e[0]||(e[0]=[n('<h1 id="models-and-logic" tabindex="-1">Models and logic <a class="header-anchor" href="#models-and-logic" aria-label="Permalink to &quot;Models and logic&quot;">​</a></h1><p>SPACE AI can help users understand how a connected IBM Planning Analytics model works and perform supported development tasks without manually navigating between cubes, dimensions, rules, processes, and other model objects.</p><p>Start with a model object or business question. The assistant can use available SPACE-controlled tools to inspect the model, follow relevant relationships and dependencies, explain the results, and perform supported changes when requested.</p><h2 id="understanding-model-structure" tabindex="-1">Understanding model structure <a class="header-anchor" href="#understanding-model-structure" aria-label="Permalink to &quot;Understanding model structure&quot;">​</a></h2><p>Ask SPACE AI about a specific model object or about the model from a business perspective. The assistant can inspect available model information and help identify the objects and logic involved.</p><p>For example:</p><ul><li><code>What updates the Revenue cube?</code></li><li><code>Which processes and rules are involved in workforce planning?</code></li><li><code>Explain the dependencies of this cube.</code></li><li><code>Where is this dimension used?</code></li></ul><p>You can continue with follow-up questions to move from a high-level explanation into specific cubes, dimensions, rules, processes, chores, or dependencies.</p><p>For visual model exploration and direct object search, see <a href="./../planning-analytics/model-documentation.html">Model documentation</a> and <a href="./../planning-analytics/model-search.html">Model search</a>.</p><h2 id="rules-and-feeders" tabindex="-1">Rules and feeders <a class="header-anchor" href="#rules-and-feeders" aria-label="Permalink to &quot;Rules and feeders&quot;">​</a></h2><p>SPACE AI can retrieve and review cube rules, explain calculation logic and feeders, and translate technical expressions into business-friendly explanations.</p><p>The assistant can also follow references to related model objects and help identify potential issues or areas that deserve closer review. Follow-up questions can focus on individual rule statements, feeders, dependencies, or the business purpose of a calculation.</p><p>For example:</p><ul><li><code>Explain how this cube calculates gross margin.</code></li><li><code>Explain these feeders and why they are needed.</code></li><li><code>Which other cubes does this rule reference?</code></li><li><code>Review this rule and suggest improvements.</code></li></ul><p>When a change is required, SPACE AI can use supported tools to create or update cube rules.</p><h2 id="turbointegrator-processes" tabindex="-1">TurboIntegrator processes <a class="header-anchor" href="#turbointegrator-processes" aria-label="Permalink to &quot;TurboIntegrator processes&quot;">​</a></h2><p>SPACE AI can retrieve and review TurboIntegrator process code and explain what a process does, how data moves through it, and which model objects it interacts with.</p><p>You can use the assistant to investigate individual sections of a process, understand dependencies, review code, or troubleshoot unexpected behavior.</p><p>For example:</p><ul><li><code>Explain what this process does.</code></li><li><code>Which cubes and dimensions does this process use?</code></li><li><code>Review this process and identify potential issues.</code></li><li><code>Why might this process be failing?</code></li></ul><p>SPACE AI can also use supported tools to create or update TurboIntegrator processes when requested.</p><p>For error investigations that require logs or execution information, see <a href="./investigating-errors.html">Investigating errors</a>.</p><h2 id="creating-and-modifying-model-objects" tabindex="-1">Creating and modifying model objects <a class="header-anchor" href="#creating-and-modifying-model-objects" aria-label="Permalink to &quot;Creating and modifying model objects&quot;">​</a></h2><p>SPACE AI can perform supported development tasks in connected TM1 models, allowing a conversation to move from understanding existing model logic to making changes.</p><p>Supported actions include creating or updating Planning Analytics objects such as:</p><ul><li>TurboIntegrator processes</li><li>Cube rules</li><li>Views</li><li>Subsets</li></ul><p>Describe the result you want and provide relevant model context. Where appropriate, the assistant can inspect existing objects and dependencies before preparing or performing the requested change using available SPACE tools.</p><p>For example:</p><ul><li><code>Update this rule to handle the new Forecast version.</code></li><li><code>Create a process that clears this cube for the selected scenario.</code></li><li><code>Create a view for Actual versus Budget by month.</code></li><li><code>Create a subset containing the active cost centers.</code></li></ul><p>Available actions depend on the connected environment, SPACE configuration, and the user&#39;s permissions.</p><p>Review and test model changes using the normal development and deployment practices for your environment. For managing changes between environments, see <a href="./../planning-analytics/releases-and-deployments.html">Releases and deployments</a>.</p><h2 id="more-examples" tabindex="-1">More examples <a class="header-anchor" href="#more-examples" aria-label="Permalink to &quot;More examples&quot;">​</a></h2><p>See <a href="./examples.html">AI examples</a> for additional model, rule, process, and development prompts. For investigations involving errors and logs, see <a href="./investigating-errors.html">Investigating errors</a>.</p>',33)]))}const m=o(t,[["render",r]]);export{h as __pageData,m as default};
